enum Dir {
    N,
    E,
    S,
    W,
}

impl Dir {
    fn turn(self) -> Self {
        match self {
            Self::N => Self::E,
            Self::E => Self::S,
            Self::S => Self::W,
            Self::W => Self::N,
        }
    }

    fn vertical(&self) -> bool {
        match *self {
            Dir::N => true,
            Dir::S => true,
            Dir::E => false,
            Dir::W => false,
        }
    }
}

fn main() {
    let d = Dir::N;
    let mut e = d;
    for _ in 0..3 {
        e = e.turn();
    }
    println!("{:?} {:?} {} {}", d, e, d.vertical(), e.vertical());
}

